independent.solution:
from datetime import datetime, timedelta

def windows(start, end, hours):
    out = []
    current = start
    while current < end:
        out.append((current, min(current + timedelta(hours=hours), end)))
        current += timedelta(hours=hours)
    return out

for lo, hi in windows(datetime(2025, 3, 1, 0), datetime(2025, 3, 1, 10), 4):
    print(f"{lo:%Y-%m-%d %H:%M} to {hi:%Y-%m-%d %H:%M}")
